const comfyuiUrls = [
  'https://vcbj5meqyp1y7ifw-8188.container.x-gpu.com',
  'https://vcbj5meqyp1y7ifw-8189.container.x-gpu.com',
  'https://vcbj5meqyp1y7ifw-8190.container.x-gpu.com',
  'https://vcbj5meqyp1y7ifw-8191.container.x-gpu.com',
  'https://vcbj5meqyp1y7ifw-8192.container.x-gpu.com'
];
return comfyuiUrls.map((url) => ({ json: { url } }));

const candidates = $('GPU 候选列表').all().map((item) => item.json.url);
const results = $input.all();
const aliveGpuUrls = [];
results.forEach((item, index) => {
  const res = item.json || {};
  if (res && res.system && res.devices && candidates[index]) {
    aliveGpuUrls.push(candidates[index]);
  }
});
if (!aliveGpuUrls.length) {
  throw new Error('没有可用的 GPU 绘图服务：5 个 ComfyUI 候选实例全部探测失败，请确认至少启动了一个 GPU 实例。');
}
return [{ json: { aliveGpuUrls, aliveCount: aliveGpuUrls.length } }];

